{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE snitch_db.maplemonk.rolling_30_days_dashboard AS WITH capsule_launch AS ( SELECT CAPSULE, LAUNCH_DATE FROM VALUES (\'Street FC\', \'2026-06-23\'::DATE), (\'Street FC Plus\', \'2026-06-23\'::DATE), (\'botanical THEME\', \'2026-07-11\'::DATE), (\'Embroided Shirts\', \'2026-07-16\'::DATE), (\'GOLF POLO THEME\', \'2026-07-27\'::DATE), (\'PHOTO PRINT\', \'2026-08-06\'::DATE), (\'Try Less Denim\', \'2026-08-14\'::DATE), (\'Festive - 1\', NULL), (\'Printed Shirts\', \'2026-09-04\'::DATE), (\'Luxe\', \'2026-09-18\'::DATE) AS t(CAPSULE, LAUNCH_DATE) ), sku_mapping AS ( SELECT DISTINCT UPPER(TRIM(SKU)) AS SKU, TRIM(COLLECTION) AS COLLECTION FROM snitch_db.maplemonk.collection_sku_mapped_sheet1 WHERE SKU IS NOT NULL AND COLLECTION IS NOT NULL ), sales_base AS ( SELECT UPPER(TRIM(h.SKU_GROUP)) AS SKU_GROUP, c.COLLECTION AS CAPSULE, cl.LAUNCH_DATE, h.DATE, h.GROSS_QUANTITY, h.GROSS_SALES, h.DISCOUNT_AMOUNT, MIN( CASE WHEN h.GROSS_QUANTITY > 0 THEN h.DATE END ) OVER ( PARTITION BY UPPER(TRIM(h.SKU_GROUP)) ) AS FIRST_SALE_DATE FROM snitch_db.maplemonk.horizontal_sales_categories h INNER JOIN sku_mapping c ON UPPER(TRIM(h.SKU_GROUP)) = UPPER(TRIM(c.SKU)) LEFT JOIN capsule_launch cl ON LOWER(TRIM(c.COLLECTION)) = LOWER(TRIM(cl.CAPSULE)) ), sales_summary AS ( SELECT SKU_GROUP, CAPSULE, LAUNCH_DATE, SUM( CASE WHEN TO_DATE(DATE) >= CURRENT_DATE() - 30 THEN GROSS_QUANTITY ELSE 0 END ) AS LAST_30_QTY, SUM( CASE WHEN TO_DATE(DATE) >= CURRENT_DATE() - 30 THEN GROSS_SALES ELSE 0 END ) AS LAST_30_GROSS_SALES, SUM( CASE WHEN TO_DATE(DATE) >= CURRENT_DATE() - 30 THEN DISCOUNT_AMOUNT ELSE 0 END ) AS LAST_30_DISCOUNT, ROUND( SUM( CASE WHEN TO_DATE(DATE) >= CURRENT_DATE() - 30 THEN GROSS_SALES ELSE 0 END ) / NULLIF( SUM( CASE WHEN TO_DATE(DATE) >= CURRENT_DATE() - 30 THEN GROSS_QUANTITY ELSE 0 END ), 0 ), 2 ) AS LAST_30_ASP, MIN(FIRST_SALE_DATE) AS FIRST_SALE_DATE, SUM( CASE WHEN DATE >= FIRST_SALE_DATE THEN GROSS_QUANTITY ELSE 0 END ) AS CUMULATIVE_SALES_QTY, SUM( CASE WHEN LAUNCH_DATE IS NOT NULL AND DATE >= LAUNCH_DATE THEN GROSS_QUANTITY ELSE 0 END ) AS LAUNCH_TO_DATE_SALES_QTY FROM sales_base GROUP BY SKU_GROUP, CAPSULE, LAUNCH_DATE HAVING COUNT( CASE WHEN TO_DATE(DATE) >= CURRENT_DATE() - 30 THEN 1 END ) > 0 ), inwards AS ( SELECT sku_group, SUM(inward_qty) AS TOTAL_INWARD_QTY FROM ( SELECT UPPER( TRIM( REVERSE( SUBSTRING( REVERSE(\"Item Type skuCode\"), CHARINDEX(\'-\', REVERSE(\"Item Type skuCode\")) + 1, LEN(\"Item Type skuCode\") ) ) ) ) AS sku_group, PUTAWAY_UPDATED::DATE AS inward_date, SUM(PUTAWAY_COMPLETED_QUANTITY) AS inward_qty FROM snitch_db.maplemonk.putaway_tracking WHERE LOWER(FINAL_TYPE) LIKE \'new%\' GROUP BY 1,2 ) GROUP BY sku_group ), rolling_30_metrics AS ( SELECT s.SKU_GROUP, s.CAPSULE, s.LAUNCH_DATE, s.LAST_30_QTY, s.LAST_30_GROSS_SALES, s.LAST_30_DISCOUNT, s.LAST_30_ASP, i.TOTAL_INWARD_QTY, s.FIRST_SALE_DATE, s.CUMULATIVE_SALES_QTY, s.LAUNCH_TO_DATE_SALES_QTY, DATEDIFF( DAY, s.FIRST_SALE_DATE, CURRENT_DATE() ) AS DAYS_ACTIVE, DATEDIFF( DAY, s.LAUNCH_DATE, CURRENT_DATE() ) AS DAYS_SINCE_LAUNCH, ROUND( ( s.CUMULATIVE_SALES_QTY / NULLIF(i.TOTAL_INWARD_QTY, 0) ) * 100, 2 ) AS STR_PERCENT_SOLD, CASE WHEN s.LAUNCH_DATE IS NULL THEN NULL WHEN DATEDIFF( DAY, s.LAUNCH_DATE, CURRENT_DATE() ) < 30 THEN ROUND( ( s.LAUNCH_TO_DATE_SALES_QTY / NULLIF(i.TOTAL_INWARD_QTY, 0) ) * 100, 2 ) ELSE ROUND( ( s.LAST_30_QTY / NULLIF(i.TOTAL_INWARD_QTY, 0) ) * 100, 2 ) END AS LAST_30_STR, CASE WHEN s.LAUNCH_DATE IS NULL THEN NULL WHEN DATEDIFF( DAY, s.LAUNCH_DATE, CURRENT_DATE() ) = 0 THEN NULL WHEN DATEDIFF( DAY, s.LAUNCH_DATE, CURRENT_DATE() ) < 30 THEN LEAST( ROUND( ( s.LAUNCH_TO_DATE_SALES_QTY / NULLIF(i.TOTAL_INWARD_QTY, 0) ) * ( 30.0 / DATEDIFF( DAY, s.LAUNCH_DATE, CURRENT_DATE() ) ) * 100, 2 ), 100 ) ELSE ROUND( ( s.LAST_30_QTY / NULLIF(i.TOTAL_INWARD_QTY, 0) ) * 100, 2 ) END AS NORMALIZED_30_STR FROM sales_summary s LEFT JOIN inwards i ON UPPER(TRIM(s.SKU_GROUP)) = UPPER(TRIM(i.SKU_GROUP)) ) SELECT r30.*, r30.LAST_30_STR AS STR, CASE WHEN LOWER(TRIM(r30.CAPSULE)) IN ( \'embroided shirts\', \'botanical theme\', \'street fc\', \'street fc plus\', \'golf polo theme\', \'photo print\', \'try less denim\', \'printed shirts\' ) THEN \'YES\' ELSE \'NO\' END AS FOCUS_CAPSULE FROM rolling_30_metrics r30 ORDER BY LAST_30_GROSS_SALES DESC;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from SNITCH_DB.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            